diff --git a/src/base/cs_boundary_conditions_set_coeffs_turb.c b/src/base/cs_boundary_conditions_set_coeffs_turb.c
index 64247d945..2ef776e64 100644
--- a/src/base/cs_boundary_conditions_set_coeffs_turb.c
+++ b/src/base/cs_boundary_conditions_set_coeffs_turb.c
@@ -277,11 +277,11 @@ _cs_boundary_conditions_set_coeffs_turb_scalar(cs_field_t  *f_sc,
   /* pointers to T+ and T* if saved */

   cs_real_t *tplusp = NULL, *tstarp = NULL;
-  cs_field_t *itplus = cs_field_by_name_try("tplus");
-  cs_field_t *itstar = cs_field_by_name_try("tstar");
