+    cs_field_t *itplus = cs_field_by_name_try("tplus");
+    cs_field_t *itstar = cs_field_by_name_try("tstar");

     if (itplus != NULL)
       tplusp = itplus->val;
@@ -933,10 +933,10 @@ _cs_boundary_conditions_set_coeffs_turb_scalar(cs_field_t  *f_sc,
       if (b_f_id >= 0)
         bvar_s[f_id] -= tplus * tet;

-      if (itplus != NULL)
+      if (tplusp != NULL)
